from collections import deque

def shortest_path(graph, source, target):
    if source not in graph or target not in graph:
        return (float('inf'), None)
    distances = {node: float('inf') for node in graph}
    path = {node: [] for node in graph}
    distances[source] = 0
    queue = deque([(source, [source])])
    while queue:
        current_node, current_path = queue.popleft()
        for neighbour, weight in graph[current_node]:
            if distances[current_node] + weight < distances[neighbour]:
                distances[neighbour] = distances[current_node] + weight
                path[neighbour] = current_path + [neighbour]
                if neighbour == target:
                    return (distances[target], path[neighbour])
                queue.append((neighbour, path[neighbour]))
    return (float('inf'), None)
